import raw from "./data/segments.json";

/** [length_m, tickCount, tickLengthM, included 0|1] — generated by scripts/build-segment-meta.mjs. */
export type SegmentTuple = readonly [lengthM: number, tickCount: number, tickLengthM: number, included: number];

export interface SegmentMeta {
  version: string;
  tickM: number;
  islandTotalM: number;
  segments: Record<string, SegmentTuple>;
  trails: Record<string, string[]>;
}

function load(src: typeof raw): SegmentMeta {
  const segments: Record<string, SegmentTuple> = {};
  for (const [id, t] of Object.entries(src.segments)) {
    const [len, n, tickLen, inc] = t;
    if (len === undefined || n === undefined || tickLen === undefined || inc === undefined) throw new Error(`bad segment meta ${id}`);
    segments[id] = [len, n, tickLen, inc];
  }
  return { version: src.version, tickM: src.tickM, islandTotalM: src.islandTotalM, segments, trails: src.trails };
}

export const META: SegmentMeta = load(raw);
